/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
import io
import unittest
import consumer
import test_consumer

source = Path('summary.py').read_text()
original = consumer.summarize
variants = {
    'baseline': source,
    'remove code fallback': (\"    code = record.get('code') or 'unknown'\\n\", \"    code = record['code']\\n\"),
    'remove display-name fallback': (\"    name = record.get('display_name') or record['name']\\n\", \"    name = record['display_name']\\n\"),
    'remove negative guard': (\"    if amount < 0:\\n        raise ValueError('negative amount')\\n\", ''),
}
expected_tests = {'baseline': (0, 0), 'remove code fallback': (1, 2), 'remove display-name fallback': (0, 0), 'remove negative guard': (1, 0)}
missing = object()
try:
    for label, change in variants.items():
        if isinstance(change, tuple):
            old, new = change
            assert source.count(old) == 1, label
            modified = source.replace(old, new, 1)
        else:
            modified = change
        namespace = {}
        exec(compile(modified, 'summary.py [in-memory ' + label + ']', 'exec', dont_inherit=True), namespace)
        consumer.summarize = namespace['summarize']
        output = io.StringIO()
        result = unittest.TextTestRunner(stream=output).run(unittest.defaultTestLoader.loadTestsFromModule(test_consumer))
        observed = (len(result.failures), len(result.errors))
        assert observed == expected_tests[label], output.getvalue()
        print(f'{label}: {result.testsRun} existing tests; failures={observed[0]}, errors={observed[1]}')
        differences = []
        for code in (missing, '', 'X'):
            for display in (missing, '', 'A'):
                for amount in (-1, 0, 2):
                    record = {'name': 'Ada', 'amount': amount}
                    if code is not missing:
                        record['code'] = code
                    if display is not missing:
                        record['display_name'] = display
                    before = dict(record)
                    try:
                        actual = ('return', consumer.render(record))
                    except Exception as exc:
                        actual = ('raise', type(exc).__name__, str(exc))
                    expected = ('raise', 'ValueError', 'negative amount') if amount < 0 else ('return', ('unknown' if code is missing or code == '' else code, 'Ada' if display is missing or display == '' else display, amount))
                    assert record == before
                    if actual "'!= expected:
                        differences.append((record, actual, expected))
        expected_differences = {'"'baseline': 0, 'remove code fallback': 15, 'remove display-name fallback': 0, 'remove negative guard': 9}
        assert len(differences) == expected_differences[label], differences
        print(f'  27 render cases: {len(differences)} contract deviations; input unchanged in all cases')
        if differences:
            print('  example:', differences[0])
finally:
    consumer.summarize = original
print('All probe assertions passed; changes existed only in memory.')
PY"

